import{_ as a,I as o,g as t,j as l}from"./chunks/framework.CjoWWfVe.js";const u=JSON.parse('{"title":"Общая информация о пространствах","description":"Какие типы рабочих пространств существуют в ОмниКрафт ЕРП, их особенности, реализованные и планируемые модули.","frontmatter":{"title":"Общая информация о пространствах","description":"Какие типы рабочих пространств существуют в ОмниКрафт ЕРП, их особенности, реализованные и планируемые модули.","order":5},"headers":[],"relativePath":"ru/docs/spaces/general.md","filePath":"ru/docs/spaces/general.md"}'),e={name:"ru/docs/spaces/general.md"};function n(s,r,i,g,h,d){return o(),t("div",null,[...r[0]||(r[0]=[l('<h1 id="🗂️-рабочие-пространства-общая-информация" tabindex="-1">🗂️ Рабочие пространства: Общая информация <a class="header-anchor" href="#🗂️-рабочие-пространства-общая-информация" aria-label="Permalink to &quot;🗂️ Рабочие пространства: Общая информация&quot;">​</a></h1><p>В основе архитектуры <strong>ОмниКрафт ЕРП</strong> лежит концепция изолированных рабочих пространств. Ремесленник, предприниматель или любой человек в своей жизни редко ограничивается одним направлением деятельности. Попытка уместить разнородную деятельность в рамках одной учетной книги неизбежно приводит к искажениям учёта, путанице на складе и неразберихе в аналитике.</p><p>Смешивать всё это в одной куче — значит разрушить экономику каждого отдельного проекта. В ОмниКрафт ЕРП вы можете создавать независимые пространства под каждую задачу, мгновенно переключаясь между ними через выдвижную боковую панель (шторку).</p><hr><h2 id="🏗️-типы-пространств-и-практические-примеры" tabindex="-1">🏗️ Типы пространств и практические примеры <a class="header-anchor" href="#🏗️-типы-пространств-и-практические-примеры" aria-label="Permalink to &quot;🏗️ Типы пространств и практические примеры&quot;">​</a></h2><p>Вы можете выбрать наиболее подходящий шаблон в зависимости от специфики вашей деятельности:</p><h3 id="🔨-1-производство-уже-реализовано" tabindex="-1">🔨 1. Производство (уже реализовано) <a class="header-anchor" href="#🔨-1-производство-уже-реализовано" aria-label="Permalink to &quot;🔨 1. Производство (уже реализовано)&quot;">​</a></h3><p>Это пространство предназначено для классического ремесленного или любого подходящего производственного цикла, где физическое сырье проходит через стадию обработки и сборки.</p><ul><li><strong>Пример:</strong> Мастерская по пошиву кожаных сумок и аксессуаров.</li><li><strong>Как это работает:</strong> Вы закупаете материалы (склад сырья), создаете технологические карты (калькулятор рецептов), планируете заказы (верстак), зачисляете готовые товары на склад готовой продукции и проводите розничные или оптовые продажи.</li></ul><h3 id="💼-2-услуги-ожидается-скоро" tabindex="-1">💼 2. Услуги (ожидается скоро) <a class="header-anchor" href="#💼-2-услуги-ожидается-скоро" aria-label="Permalink to &quot;💼 2. Услуги (ожидается скоро)&quot;">​</a></h3><p>Шаблон для направлений, связанных с выполнением работ, ремонтом, консультированием или фрилансом, где нет необходимости вести учет серийного производства.</p><ul><li><strong>Пример:</strong> Ремонт и реставрация изделий, частное консультирование, дизайн на заказ или фриланс-услуги.</li><li><strong>Как это работает:</strong> Основной упор здесь делается на учет времени, потраченного на оказание услуги, и фиксацию оплат от клиентов. Склад готовой продукции в данном шаблоне отсутствует за ненадобностью, так как вы продаете свой труд и навыки, а не типовые товары с витрины.</li></ul><h3 id="🛒-3-торговля-ритеил-ожидается-скоро" tabindex="-1">🛒 3. Торговля / Ритейл (ожидается скоро) <a class="header-anchor" href="#🛒-3-торговля-ритеил-ожидается-скоро" aria-label="Permalink to &quot;🛒 3. Торговля / Ритейл (ожидается скоро)&quot;">​</a></h3><p>Вариант для направлений, исключающих производственную фазу.</p><ul><li><strong>Пример:</strong> Продажа сопутствующих товаров, например, инструментов для кожевенников, химии или фурнитуры.</li><li><strong>Как это работает:</strong> Вы закупаете готовые товары оптом, приходуете их непосредственно на витрину и реализуете с наценкой. Цепочка сборки изделий здесь исключена, настраивая интерфейс под чистые торговые операции.</li></ul><h3 id="🌐-4-обучение-цифровые-товары-ожидается-скоро" tabindex="-1">🌐 4. Обучение / Цифровые товары (ожидается скоро) <a class="header-anchor" href="#🌐-4-обучение-цифровые-товары-ожидается-скоро" aria-label="Permalink to &quot;🌐 4. Обучение / Цифровые товары (ожидается скоро)&quot;">​</a></h3><p>Пространство для продажи цифровых продуктов, где себестоимость копирования стремится к нулю.</p><ul><li><strong>Пример:</strong> Продажа авторских электронных лекал, лекал, видеоуроков или проведение живых мастер-классов.</li><li><strong>Как это работает:</strong> Вы не списываете физические материалы при каждой продаже. Учет ориентирован на фиксацию прибыли от дистрибуции контента и анализ эффективности каналов привлечения клиентов.</li></ul><h3 id="🌱-5-деятельность-хобби-ожидается-скоро" tabindex="-1">🌱 5. Деятельность / Хобби (ожидается скоро) <a class="header-anchor" href="#🌱-5-деятельность-хобби-ожидается-скоро" aria-label="Permalink to &quot;🌱 5. Деятельность / Хобби (ожидается скоро)&quot;">​</a></h3><p>Песочница для некоммерческих увлечений или проектов на стадии зарождения.</p><ul><li><strong>Пример:</strong> Любительское увлечение керамикой, домашнее пивоварение или садоводство.</li><li><strong>Как это работает:</strong> Вы просто фиксируете расходы на покупку материалов и оборудования, чтобы понимать, во сколько вам обходится увлечение.</li></ul><div class="tip custom-block"><p class="custom-block-title">Плавный переход в бизнес</p><p>Если ваше хобби начинает приносить доход, пространство «Деятельность / Хобби» можно в любой момент бесшовно перевести в статус коммерческого (например, «Производство» или «Услуги»), сохранив всю накопленную историю закупок и базу рецептов.</p></div><h3 id="🏦-6-личное-ожидается-скоро" tabindex="-1">🏦 6. Личное (ожидается скоро) <a class="header-anchor" href="#🏦-6-личное-ожидается-скоро" aria-label="Permalink to &quot;🏦 6. Личное (ожидается скоро)&quot;">​</a></h3><p>Пространство для ведения учёта личных активов, планирования жизни и целеполагания.</p><ul><li><strong>Пример:</strong> Собственная квартира, личный автомобиль, дорогая техника, а также значимые жизненные события (оплата ипотеки, покупка бытовой техники, получение крупного наследства или оплата дорогостоящего обучения).</li><li><strong>Как это работает:</strong> В этом пространстве вы можете эффективно структурировать свою жизнь: намечать ключевые направления деятельности, исходя из ваших желаний и насущных необходимостей, и ставить внутри этих направлений конкретные цели. Цели могут быть как денежными (например, накопить на ремонт или закрыть кредит), так и абсолютно любыми другими (например, пройти обучение или освоить новый навык). Здесь же вы фиксируете свое крупное личное имущество (нефинансовые активы) и отмечаете только значимые разовые приходы и расходы.</li><li><strong>Главное преимущество:</strong> вам больше не нужно вести учет мелких повседневных покупок (продукты, кофе, бензин) — вся подобная рутина уходит в прошлое. Программа на глобальной сводной панели <strong>«Мой капитал»</strong> автоматически посчитает все ваши фоновые траты на основе остатков на счетах и картах. Вам достаточно вносить эти остатки с желаемой периодичностью (например, раз в месяц), чтобы наблюдать за ростом или изменением уровня вашего реального богатства в динамике.</li></ul><hr><h2 id="💡-масштабирование-любое-количество-пространств" tabindex="-1">💡 Масштабирование: Любое количество пространств <a class="header-anchor" href="#💡-масштабирование-любое-количество-пространств" aria-label="Permalink to &quot;💡 Масштабирование: Любое количество пространств&quot;">​</a></h2><p>Вы не ограничены рамками «один тип деятельности — одно пространство». Программа позволяет создавать несколько пространств одного типа, если у вас параллельно развивается несколько разных проектов.</p><p>Например, если вы занимаетесь и кожевничеством, и столярным делом, вы можете завести два независимых пространства типа <strong>«Производство»</strong> (например, «Кожаные изделия» и «Деревянная мебель»). А если помимо этого вы занимаетесь реставрацией изделий и берете заказы на графический дизайн, вы можете создать для них отдельные пространства типа <strong>«Услуги»</strong> (например, «Реставрация» и «Фриланс»). Это позволяет полностью разделить их экономику, наценки и складские запасы.</p><hr><h2 id="🏦-консолидация-капитала-модуль-«мои-капитал»-уже-реализовано" tabindex="-1">🏦 Консолидация капитала: Модуль «Мой капитал» (уже реализовано) <a class="header-anchor" href="#🏦-консолидация-капитала-модуль-«мои-капитал»-уже-реализовано" aria-label="Permalink to &quot;🏦 Консолидация капитала: Модуль «Мой капитал» (уже реализовано)&quot;">​</a></h2><p>Несмотря на то, что экономика каждого вашего проекта ведется изолированно, в ПРО-режиме ОмниКрафт ЕРП реализован глобальный модуль <strong>«Мой капитал»</strong> (вызывается отдельной кнопкой в боковой панели).</p><p>Этот модуль объединяет показатели всех ваших рабочих пространств и освобождает вас от необходимости вести детальный микроучет мелких повседневных личных трат (на кофе, продукты, бензин и т.д.).</p><h3 id="как-устроен-учет-в-модуле-«мои-капитал»" tabindex="-1">Как устроен учет в модуле «Мой капитал»: <a class="header-anchor" href="#как-устроен-учет-в-модуле-«мои-капитал»" aria-label="Permalink to &quot;Как устроен учет в модуле «Мой капитал»:&quot;">​</a></h3><ol><li><strong>Мои счета:</strong> На этой вкладке вы один раз заводите свои реальные банковские карты, наличные кошельки, вклады или брокерские счета. Вам <strong>не нужно</strong> вносить туда каждую мелкую трату. Вместо этого вы просто периодически (например, раз в месяц) заходите и обновляете фактические остатки на этих счетах.</li><li><strong>Мои активы и значимые операции:</strong> Сюда программа автоматически подтягивает данные из вашего пространства <strong>«Личное»</strong> (стоимость вашего автомобиля, квартиры, а также крупные зафиксированные доходы и расходы).</li><li><strong>Автоматическая консолидация:</strong> Программа складывает остатки на ваших счетах, стоимость материалов на складах, оценку товаров на витринах и стоимость оборудования всех ваших пространств.</li><li><strong>Расчет свободных трат (Дельта):</strong> Программа берет совокупную прибыль всей вашей деятельности, прибавляет значимые личные доходы, вычитает значимые расходы и сравнивает это с фактическим ростом денег на ваших личных счетах. На основе этой разницы система сама рассчитывает баланс неучтенных повседневных мелочей — объединяя все ваши мелкие бытовые расходы и небольшие случайные приходы (помимо внесенных вами крупных значимых событий). Это избавляет вас от рутины, наглядно показывая на графиках реальную динамику вашего благосостояния.</li></ol><hr><h2 id="🧭-управление-пространствами-и-встроенныи-помощник" tabindex="-1">🧭 Управление пространствами и встроенный помощник <a class="header-anchor" href="#🧭-управление-пространствами-и-встроенныи-помощник" aria-label="Permalink to &quot;🧭 Управление пространствами и встроенный помощник&quot;">​</a></h2><p>В верхней панели окна приложения расположены компактные кнопки быстрого доступа:</p><ul><li><strong>Кнопка рабочих пространств (<code>⛯</code>):</strong> открывает боковую шторку для быстрого переключения между производствами, личными финансами или модулями без перегрузки интерфейса.</li><li><strong>Встроенный ИИ-помощник (<code>✨</code>):</strong> вызывается кнопкой в заголовке или сочетанием клавиш <code>Ctrl + J</code>. <ul><li>Помощник открывается в виде боковой панели во всю высоту окна, <strong>не затемняя</strong> рабочие таблицы и позволяя сразу видеть любые изменения данных в реальном времени.</li><li>Ширину панели можно свободно изменять мышью, потянув за левую границу — программа запомнит удобный размер для вашего монитора.</li><li><strong>Шторка диалогов и проекты (<code>≡</code>):</strong> в шапке панели доступно меню управления переписками. Вы можете создавать отдельные диалоги под разные задачи, группировать их по папкам-проектам (например, «Новая коллекция» или «Налоговый аудит») и закреплять важные обсуждения булавкой (📌) вверху списка.</li><li><strong>История и экспорт:</strong> вся переписка сохраняется в базе данных с привязкой к активному пространству. Любой диалог можно в один клик экспортировать в читаемый файл Markdown через меню сессии.</li><li><strong>Ленивая подгрузка сообщений:</strong> длинные диалоги загружаются порциями (по 25 реплик) с кнопкой просмотра более ранней переписки, гарантируя мгновенный отклик интерфейса.</li><li>Помощник автоматически видит открытый экран и одновременно имеет доступ ко всей базе через инструменты системы.</li><li>В настройках помощника (значок шестерёнки в шапке чата) доступна опция <strong>«Вносить правки только на текущей вкладке»</strong> (включена по умолчанию): она защищает от случайных автоматических правок в соседних разделах цеха.</li></ul></li></ul>',39)])])}const p=a(e,[["render",n]]);export{u as __pageData,p as default};
